local function flatten_table( t )
	local buffer = ""
	for k, v in pairs(t) do
		if buffer:len() > 0 then buffer = buffer .. ", " end
		buffer = buffer .. tostring(k) .. ": "
		if type(v) == "table" then
			buffer = buffer .. flatten_table(v)
		else
			buffer = buffer .. tostring(v)
		end
	end
	return buffer
end

