local os_date_hold

function TestVendViewEnter:setUp()
 	kernel = newluaunitmockkernel()
	MasterProductCatalog = newluaunitmockworktable()

	os_date_hold = os.date
	os.date = function() return now end
	idle_timer = newidletimer()
	culture_idle_timer = newidletimer( "culture_idle_timer" )
end

function TestVendViewEnter:tearDown()
 	kernel = nil
	MasterProductCatalog = nil
	os.date = os_date_hold

end

